import type { ChildProcess } from "node:child_process"
import type { ExecutionProcessBroker, ExecutionResourceBudget } from "../execution/types.js"

/** Kinds of tasks that can run in the background. Shell is the only one
 *  implemented today; the union exists so the store doesn't need rework
 *  when we add agent-backed background tasks later. */
export type TaskKind = "shell"

/** Runtime state for one background task. Mutable — fields are written
 *  as the underlying process makes progress. */
export interface Task {
  /** Stable id (8 hex chars), generated by the store. Returned to the model
   *  and used as the lookup key everywhere. */
  taskId: string
  kind: TaskKind
  /** Command line as submitted. */
  command: string
  /** Short label for UI / completion notification. Falls back to the first
   *  60 chars of `command` when the caller didn't supply one. */
  description: string
  /** Absolute path of the log file containing interleaved stdout+stderr. */
  outputFile: string
  /** OS pid. Set on successful spawn. */
  pid: number
  startedAt: number
  /** Set after the process exits and captured output has flushed to disk. */
  exitedAt?: number
  exitCode?: number | null
  signal?: NodeJS.Signals | null
  /** Conversation that launched the task; distinct from child-agent ownership. */
  sessionId?: string
  /** Owning agent id when the spawner is a sub-agent. Used by
   *  `killByOwner` to clean up when the sub-agent terminates so the
   *  child doesn't reparent to init. Undefined = main session. */
  ownerAgentId?: string
  /** Live process handle. NOT included in snapshots / events. */
  child?: ChildProcess
}

/** Read-only view of a Task — child handle stripped. This is the shape
 *  consumed by tools, UI, and the completion-notification emitter. */
export type TaskSnapshot = Omit<Task, "child">

export interface SpawnShellOptions {
  command: string
  /** Working directory for the shell process. Defaults to this process cwd. */
  cwd?: string
  /** Optional human label. Defaults to `command.slice(0, 60)`. */
  description?: string
  /** Conversation that launched the task. */
  sessionId?: string
  /** Agent that spawned this task. Drives lifecycle cleanup on agent exit. */
  ownerAgentId?: string
  /** Broker-owned process launcher supplied by ExecutionBroker. */
  process?: ExecutionProcessBroker
  /** Trusted runtime variables explicitly preserved by the calling tool. */
  preserveEnvironment?: string[]
  /** Effective broker cap and meter for this task's captured output. */
  maxOutputBytes?: number
  resources?: ExecutionResourceBudget
}

/** Payload for the 'started' / 'exited' EventEmitter events. */
export interface TaskStartedEvent {
  task: TaskSnapshot
}

export interface TaskExitedEvent {
  taskId: string
  exitCode: number | null
  signal: NodeJS.Signals | null
  /** Total bytes written to outputFile. */
  outputBytes: number
}
